"""Base class for optimization experts."""

from __future__ import annotations

import abc

from ..models import Recommendation, SystemContext


class Expert(abc.ABC):
    """Abstract expert that analyzes system context and produces recommendations."""

    @abc.abstractmethod
    def analyze(self, context: SystemContext) -> list[Recommendation]:
        """Analyze system context and return optimization recommendations."""

    @staticmethod
    def filter_by_confidence(
        recommendations: list[Recommendation],
        min_confidence: float = 0.6,
    ) -> list[Recommendation]:
        """Filter recommendations below confidence threshold."""
        return [r for r in recommendations if r.confidence >= min_confidence]
